import{_ as l,a0 as o,w as n,s,ao as S,I as p,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"學習 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT x X-CMD","titleTemplate":false,"description":"學習 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220720 How much JavaScript do you need to know before learning ReactJS-","title":"學習 ReactJS 之前，你需要了解多少 JavaScript？","tag":"202207","desc":""},"relativePath":"202207/20220720 How much JavaScript do you need to know before learning ReactJS-.md","filePath":"[post].md"}'),c={name:"202207/20220720 How much JavaScript do you need to know before learning ReactJS-.md"};function d(J,a,u,v,m,f){const e=o("Link");return n(),s("div",null,[a[18]||(a[18]=S('<h1 id="學習-reactjs-之前-你需要了解多少-javascript" tabindex="-1">學習 ReactJS 之前，你需要了解多少 JavaScript？ <a class="header-anchor" href="#學習-reactjs-之前-你需要了解多少-javascript" aria-label="Permalink to “學習 ReactJS 之前，你需要了解多少 JavaScript？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/29/082104d5zn1xn77r1n8p1n.jpg" alt=""></p><blockquote><p>最主要的是要精通 JavaScript，這樣你就可以減少 ReactJS 之旅的複雜性。</p></blockquote><p>React 是一個建立在 HTML、CSS 和 JavaScript 之上的 UI 框架，其中 JavaScript（JS）負責大部分的邏輯。如果你對變量、數據類型、數組函數、回調、作用域、字符串方法、循環和其他 JS DOM 操作相關的主題有一定了解，這些將極大地加快學習 ReactJS 的步伐。</p><p>你對現代 JavaScript 的概念將決定你能多快地掌握 ReactJS 的步伐。你不需要成為一個 JavaScript 專家來開始你的 ReactJS 之旅，但就像對食材的瞭解是任何希望掌握烹飪的廚師所必須的一樣，學習 ReactJS 也是如此。它是一個現代的 JavaScript UI 庫，所以你需要了解一些 JavaScript。問題是，需要多少？</p><h3 id="示例解釋" tabindex="-1">示例解釋 <a class="header-anchor" href="#示例解釋" aria-label="Permalink to “示例解釋”">​</a></h3><p>假設我被要求用英語寫一篇關於“牛”的文章，但我對這種語言一無所知。在這種情況下，為了讓我成功地完成任務，我不僅要對主題有概念，還要對指定的語言有概念。</p><p>假設我獲得了一些關於主題（牛）的知識，我如何計算我需要知道多少英語才能寫出規定的主題？如果我必須用英語寫一篇關於其他複雜話題的文章呢？</p><p>這很難搞清楚，不是嗎？我不知道我要寫關於這個話題的什麼東西，但它可能是任何東西。所以要想開始，我必須要有適當的英語知識，但還不止於此。</p><h3 id="極端現實" tabindex="-1">極端現實 <a class="header-anchor" href="#極端現實" aria-label="Permalink to “極端現實”">​</a></h3><p>在開始使用 ReactJS 之前，所需的 JavaScript 數量也是如此。根據我的例子情景，ReactJS 是話題“牛”，而 JavaScript 是英語。要想在 ReactJS 中獲得成功，對 JavaScript 的掌握很重要。如果沒有適當的 JavaScript 基礎，一個人是很難專業地掌握 ReactJS 的。無論我對這個主題有多少知識，如果我不知道語言的基礎，我就不能正確地表達自己。</p><h3 id="多少才算夠" tabindex="-1">多少才算夠？ <a class="header-anchor" href="#多少才算夠" aria-label="Permalink to “多少才算夠？”">​</a></h3><p>根據我的經驗，當你開始你的 ReactJS 之旅時，你應該已經熟悉了：</p><ul><li>變量</li><li>數據類型</li><li>字符串方法</li><li>循環</li><li>條件式</li></ul><p>你應該對這些具體的 JavaScript 熟悉。但這些只是最基本的先決條件。當你試圖創建一個簡單的 React 應用時，你將不可避免地需要處理事件。所以，普通函數、函數表達式、語句、箭頭函數的概念，箭頭函數和普通函數的區別，以及這兩類函數中 <code>this</code> 關鍵字的詞義範圍，這確實很重要。</p><p>但問題是，如果我必須使用 ReactJS 創建一個複雜的應用怎麼辦？</p><h3 id="獲得啓發" tabindex="-1">獲得啓發 <a class="header-anchor" href="#獲得啓發" aria-label="Permalink to “獲得啓發”">​</a></h3><p>在 JavaScript 中處理事件、傳播操作符、解構、命名導入和默認導入將幫助你理解 React 代碼的工作機制。</p><p>最重要的是，你必須瞭解 JavaScript 本身背後的核心概念。JavaScript 在設計上是異步的。當出現在文件底部的代碼在文件頂部的代碼之前執行時，不要驚訝。像 promise、callback、async-await、map、filter 和 reduce 這樣的結構，是 ReactJS 中最常見的方法和概念，尤其是在開發複雜的應用時。</p><p>最主要的是要精通 JavaScript，這樣你可以減少 ReactJS 之旅的複雜性。</p><h3 id="越來越好" tabindex="-1">越來越好 <a class="header-anchor" href="#越來越好" aria-label="Permalink to “越來越好”">​</a></h3><p>我很容易説出你需要知道的東西，但你去學習它完全是另一回事。大量練習 JavaScript 是必不可少的，但你可能會感到驚訝，我認為這並不意味着你必須等到掌握它。有些概念事先很重要，但你可以在學習過程中學到很多東西。練習的一部分是學習，所以你可以開始使用 JavaScript，甚至是 React 的一些基礎知識，只要你以舒適的速度移動並理解在你嘗試任何嚴肅的事情之前做你的“家庭作業”是一個要求。</p><h3 id="立即開始使用-javascript" tabindex="-1">立即開始使用 JavaScript <a class="header-anchor" href="#立即開始使用-javascript" aria-label="Permalink to “立即開始使用 JavaScript”">​</a></h3>',23)),p("p",null,[a[1]||(a[1]=t("不要費心等到你瞭解了 JavaScript 的所有方面。那永遠不會發生。如果這樣做，你將陷入學習 JavaScript 的永遠循環中。你們都知道技術領域是如何不斷發展和迅速變化的。如果你想開始學習 JavaScript，請嘗試閲讀 Mandy Kendall 的介紹性文章 ",-1)),r(e,{href:"https://opensource.com/article/21/1/learn-javascript"},{default:i(()=>[...a[0]||(a[0]=[t("通過編寫猜謎遊戲學習 JavaScript",-1)])]),_:1}),a[2]||(a[2]=t("。這是一種快速入門的好方法，當你看到了可能的情況，我認為你可能會發現很難停下來。",-1))]),a[19]||(a[19]=p("hr",null,null,-1)),p("p",null,[a[4]||(a[4]=t("via: ",-1)),r(e,{href:"https://opensource.com/article/22/7/learn-javascript-before-reactjs"},{default:i(()=>[...a[3]||(a[3]=[t("https://opensource.com/article/22/7/learn-javascript-before-reactjs",-1)])]),_:1})]),p("p",null,[a[9]||(a[9]=t("作者：",-1)),r(e,{href:"https://opensource.com/users/sacsam005"},{default:i(()=>[...a[5]||(a[5]=[t("Sachin Samal",-1)])]),_:1}),a[10]||(a[10]=t(" 選題：",-1)),r(e,{href:"https://github.com/lkxed"},{default:i(()=>[...a[6]||(a[6]=[t("lkxed",-1)])]),_:1}),a[11]||(a[11]=t(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[7]||(a[7]=[t("geekpi",-1)])]),_:1}),a[12]||(a[12]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[8]||(a[8]=[t("wxy",-1)])]),_:1})]),p("p",null,[a[15]||(a[15]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[13]||(a[13]=[t("LCTT",-1)])]),_:1}),a[16]||(a[16]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...a[14]||(a[14]=[t("Linux中國",-1)])]),_:1}),a[17]||(a[17]=t(" 榮譽推出",-1))])])}const x=l(c,[["render",d]]);export{b as __pageData,x as default};
